        [Test]
        public void EmbeddedReferencesRetainExactOriginalBytesAndOptionalEvidenceCopy()
        {
            var raw=LocalSaveContractFixtures.FixedGoldenBytes();Assert.That(raw.Length,Is.EqualTo(9988353));Assert.That(LocalSaveContractFixtures.Sha(raw),Is.EqualTo("ee0ef35bd3dbf03396fc5fd30389b9e75e486f8b08982b2efde3ffec1cba4ed0"));var other=(byte[])Assembly.Load("STP.Tests.Application.EditMode").GetType("STP.Tests.Application.EditMode.LocalSaveContractFixtures",true)!.GetMethod("FixedGoldenBytes")!.Invoke(null,null)!;Assert.That(other,Is.EqualTo(raw));string evidence=LocalSaveContractFixtures.EvidencePath("GOLDENS_PRECODEC_V7.json");if(System.IO.File.Exists(evidence))Assert.That(System.IO.File.ReadAllBytes(evidence),Is.EqualTo(raw));
        }
        [TestCase("V2_OWNERSHIP_MILESTONE","eligibilityContractVersion","SAVE_ELIGIBILITY_CONTRACT_UNSUPPORTED",false)]
        [TestCase("V2_OWNERSHIP_MILESTONE","eligibilityContractVersion","SAVE_ELIGIBILITY_CONTRACT_UNSUPPORTED",true)]
        [TestCase("V2_COSMETIC_RESERVED","eligibilityContractVersion","SAVE_ELIGIBILITY_CONTRACT_UNSUPPORTED",false)]
        [TestCase("V2_COSMETIC_RESERVED","eligibilityContractVersion","SAVE_ELIGIBILITY_CONTRACT_UNSUPPORTED",true)]
        [TestCase("V2_OWNERSHIP_LEGACY_ENTITLEMENT","sourceSaveSchemaVersion","SAVE_LEGACY_READER_UNSUPPORTED",false)]
        [TestCase("V2_OWNERSHIP_LEGACY_ENTITLEMENT","sourceSaveSchemaVersion","SAVE_LEGACY_READER_UNSUPPORTED",true)]
        public void UnknownOrMissingRetainedReaderVersionIsProtectedAsUnsupported(string name,string field,string expected,bool missing)
        {
            var c=LocalSaveContractFixtures.Case(name);var codec=LocalSaveContractFixtures.CodecFor(c);var bytes=LocalSaveContractFixtures.MutatePayload(c,p=>missing?p.Replace("\""+field+"\":1,","").Replace(",\""+field+"\":1",""):p.Replace("\""+field+"\":1","\""+field+"\":2"));var result=codec.Decode(bytes);Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Unsupported),result.ErrorCode);Assert.That(result.ErrorCode,Is.EqualTo(expected));Assert.That(LocalSaveContractFixtures.Property(result,"Snapshot"),Is.Null);
        }
        [TestCase("STP-SOLUTION-JCS-1")][TestCase("STP-PROOF-JCS-1")]
        public void UnknownActiveEndlessHashProfileIsProtectedAsUnsupported(string profile)
        {
            var c=LocalSaveContractFixtures.Case("V2_FULL_RESERVED_ROUNDTRIP");var codec=LocalSaveContractFixtures.CodecFor(c);var bytes=LocalSaveContractFixtures.MutatePayload(c,p=>p.Replace("\"profile\":\""+profile+"\"","\"profile\":\"UNKNOWN-FUTURE-HASH-2\""));var result=codec.Decode(bytes);Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Unsupported),result.ErrorCode);Assert.That(result.ErrorCode,Is.EqualTo("SAVE_HASH_PROFILE_UNSUPPORTED"));
        }
        [Test]
        public void PostClearAndOpenEndlessCannotHoldSameClaimThroughDifferentOperations()
        {
            var c=LocalSaveContractFixtures.Case("V2_ENDLESS_CLAIM_PROVIDER_RESERVED");var open=c.Get("sourceEnvelope").Get("payload").Get("endless").Get("openEndless").Items[0];string id=open.Get("id").Text,claim=open.Get("claim").Get("claimId").Text;string catalog=Encoding.UTF8.GetString(c.Get("sourceEnvelope").Get("payload").Get("profile").Get("catalogSet").Get("completionCatalog").Canonical());string duplicate="{\"recordVersion\":1,\"kind\":\"POST_CLEAR_PATIENCE\",\"puzzleIdentity\":{\"puzzleId\":\""+id+"\",\"profile\":\"STP-PUZZLE-SEMANTIC-JCS-1\",\"sha256\":\""+new string('b',64)+"\"},\"claimId\":\""+claim+"\",\"localOperationId\":\"different-operation\",\"providerOperationId\":null,\"claimStatus\":\"CLOSED_NO_REWARD\",\"completionCatalog\":"+catalog+",\"terminal\":null}";var bytes=LocalSaveContractFixtures.MutatePayload(c,p=>p.Replace("\"rewardClaims\":[]","\"rewardClaims\":["+duplicate+"]"));var result=LocalSaveContractFixtures.CodecFor(c).Decode(bytes);Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Corrupt),result.ErrorCode);Assert.That(result.ErrorCode,Is.EqualTo("SAVE_DUPLICATE_ID"));
        }
        public static IEnumerable<string> PositiveNames()=>LocalSaveContractFixtures.Bundle.Get("cases").Items.Select(c=>c.Get("name").Text).ToArray();
        [TestCase("utf8")][TestCase("float")][TestCase("exponent")][TestCase("unsafe-integer")][TestCase("surrogate")][TestCase("duplicate")][TestCase("unknown-envelope")][TestCase("truncation")][TestCase("trailing")]
        public void UntrustedLexicalAndEnvelopeMutationsFailClosedWithoutChangingOriginalBytes(string kind)
        {
            var c=LocalSaveContractFixtures.Case("V1_FULL_FIRST_CLEAR");string source=c.Get("expectedEnvelopeUtf8").Text;byte[] bytes;switch(kind){case "utf8":bytes=new byte[]{0x7b,0x22,0xc0,0xaf,0x22,0x3a,0x30,0x7d};break;case "float":bytes=Encoding.UTF8.GetBytes(source.Replace("\"generation\":8","\"generation\":8.0"));break;case "exponent":bytes=Encoding.UTF8.GetBytes(source.Replace("\"generation\":8","\"generation\":8e0"));break;case "unsafe-integer":bytes=Encoding.UTF8.GetBytes(source.Replace("\"generation\":8","\"generation\":9007199254740992"));break;case "surrogate":bytes=Encoding.UTF8.GetBytes(source.Replace("\"appVersion\":\"contract-1\"","\"appVersion\":\"\\ud800\""));break;case "duplicate":bytes=Encoding.UTF8.GetBytes("{\"generation\":7,"+source.Substring(1));break;case "unknown-envelope":bytes=Encoding.UTF8.GetBytes("{\"futureEnvelopeField\":1,"+source.Substring(1));break;case "truncation":bytes=Encoding.UTF8.GetBytes(source.Substring(0,source.Length-1));break;default:bytes=Encoding.UTF8.GetBytes(source+"x");break;}Assert.That(bytes.SequenceEqual(Encoding.UTF8.GetBytes(source)),Is.False);var original=(byte[])bytes.Clone();var result=LocalSaveContractFixtures.CodecFor(c).Decode(bytes);Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Corrupt),result.ErrorCode);Assert.That(LocalSaveContractFixtures.Property(result,"Snapshot"),Is.Null);Assert.That(result.ErrorCode,Is.Not.Null.And.Not.Empty);Assert.That(bytes,Is.EqualTo(original));Assert.That(result.SourceBytesSha256,Is.EqualTo(LocalSaveContractFixtures.Sha(original)));
        }
        [Test]
        public void UnicodeDiagnosticsAndWhitespacePreservePayloadAuthorityAndExactOriginalByteProvenance()
        {
            var codec=LocalSaveContractFixtures.Codec();var snapshot=LocalSaveContractFixtures.Snapshot();const string unicode="Ö\n\t😀\ue000";var bytes=(byte[])typeof(LocalSaveCodec).GetMethod("Encode")!.Invoke(codec,new[]{snapshot,(object)"2026-10-19T00:00:00.000Z",unicode,"unicode-build"})!;var padded=Encoding.UTF8.GetBytes(" \n"+Encoding.UTF8.GetString(bytes)+"\r\n");var a=codec.Decode(bytes);var b=codec.Decode(padded);Assert.That(a.Status,Is.EqualTo(LocalSaveDecodeStatus.Valid),a.ErrorCode);Assert.That(b.Status,Is.EqualTo(LocalSaveDecodeStatus.Valid),b.ErrorCode);Assert.That(b.AppVersion,Is.EqualTo(unicode));Assert.That(b.CreatedAtUtc,Is.EqualTo("2026-10-19T00:00:00.000Z"));Assert.That(a.SourcePayloadSha256,Is.EqualTo(b.SourcePayloadSha256));Assert.That(a.SourceBytesSha256,Is.Not.EqualTo(b.SourceBytesSha256));Assert.That(b.SourceBytesSha256,Is.EqualTo(LocalSaveContractFixtures.Sha(padded)));
        }
        [TestCase("bytes","LVL-PARSE-SIZE")][TestCase("depth","LVL-PARSE-DEPTH")][TestCase("string","LVL-PARSE-STRING-LENGTH")][TestCase("array","LVL-PARSE-ARRAY-LENGTH")][TestCase("members","LVL-PARSE-OBJECT-MEMBERS")]
        public void AgreedResourceLimitsStopTheActualStrictPortBeforeDtoMapping(string kind,string expected)
        {
            byte[] bytes;switch(kind){case "bytes":bytes=Enumerable.Repeat((byte)' ',67108865).ToArray();break;case "depth":bytes=Encoding.UTF8.GetBytes(new string('[',65)+"0"+new string(']',65));break;case "string":bytes=Encoding.UTF8.GetBytes("\""+new string('x',65537)+"\"");break;case "array":bytes=Encoding.UTF8.GetBytes("["+string.Join(",",Enumerable.Repeat("0",1048577))+"]");break;default:bytes=Encoding.UTF8.GetBytes("{"+string.Join(",",Enumerable.Range(0,257).Select(i=>"\"p"+i+"\":0"))+"}");break;}var hash=LocalSaveContractFixtures.Sha(bytes);var result=LocalSaveContractFixtures.Codec().Decode(bytes);Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Corrupt));Assert.That(result.ErrorCode,Is.EqualTo(expected));Assert.That(result.SourceBytesSha256,Is.EqualTo(hash));Assert.That(LocalSaveContractFixtures.Property(result,"Snapshot"),Is.Null);
        }
        [Test]
        public void TwentyFull10x10DraftsRetain256UndoAndAll300CommandIdsWithMeasuredDesktopSize()
        {
            var snapshot=Assembly.Load("STP.Tests.Application.EditMode").GetType("STP.Tests.Application.EditMode.LocalSaveContractFixtures",true)!.GetMethod("CreateStressSnapshot")!.Invoke(null,null)!;var codec=LocalSaveContractFixtures.Codec();var allocated=typeof(GC).GetMethod("GetAllocatedBytesForCurrentThread",Type.EmptyTypes);long? startAllocated=allocated==null?(long?)null:(long)allocated.Invoke(null,null)!;long startRetained=GC.GetTotalMemory(true);var watch=System.Diagnostics.Stopwatch.StartNew();var bytes=LocalSaveContractFixtures.Encode(codec,snapshot);var result=codec.Decode(bytes);watch.Stop();long? totalAllocated=allocated==null?(long?)null:(long)allocated.Invoke(null,null)!-startAllocated;long retainedDelta=GC.GetTotalMemory(false)-startRetained;Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Valid),result.ErrorCode);var payload=LocalSaveContractFixtures.Property(LocalSaveContractFixtures.Property(result,"Snapshot")!,"Payload")!;var drafts=((System.Collections.IEnumerable)LocalSaveContractFixtures.Property(payload,"Drafts")!).Cast<object>().ToArray();Assert.That(drafts.Length,Is.EqualTo(20));foreach(var draft in drafts){var cp=LocalSaveContractFixtures.Property(draft,"Checkpoint")!;Assert.That(((System.Collections.IEnumerable)LocalSaveContractFixtures.Property(cp,"Cells")!).Cast<object>().Count(),Is.EqualTo(100));Assert.That(((System.Collections.IEnumerable)LocalSaveContractFixtures.Property(cp,"UndoStack")!).Cast<object>().Count(),Is.EqualTo(256));Assert.That(((System.Collections.IEnumerable)LocalSaveContractFixtures.Property(cp,"AppliedCommandIds")!).Cast<object>().Count(),Is.EqualTo(300));}Assert.That(bytes.Length,Is.LessThan(67108864));TestContext.WriteLine("STRESS_DESKTOP_ONLY bytes="+bytes.Length+" elapsedMs="+watch.ElapsedMilliseconds+" allocatedCurrentThread="+(totalAllocated?.ToString()??"unavailable")+" retainedManagedDelta="+retainedDelta+" drafts=20 grid=10x10 undoPerDraft=256 changesPerUndo=1 dedupPerDraft=300; no physical mobile or maximum-batch allocation claim");
        }
        [Test]
        public void WriterLimitFailurePreservesTheOfferedImmutablePayloadAndItsCompleteDeduplication()
        {
            var codec=LocalSaveContractFixtures.Codec();var snapshot=LocalSaveContractFixtures.Snapshot();var payload=LocalSaveContractFixtures.Property(snapshot,"Payload")!;var before=(byte[])typeof(LocalSaveCodec).GetMethod("PayloadBytes")!.Invoke(codec,new[]{payload})!;var error=Assert.Throws<TargetInvocationException>(()=>typeof(LocalSaveCodec).GetMethod("Encode")!.Invoke(codec,new[]{snapshot,(object)"2026-10-19T00:00:00Z",new string('x',65537),"contract-build"}));Assert.That(error!.InnerException!.Message,Is.EqualTo("LVL-PARSE-STRING-LENGTH"));Assert.That(LocalSaveContractFixtures.Property(snapshot,"Payload"),Is.SameAs(payload));Assert.That((byte[])typeof(LocalSaveCodec).GetMethod("PayloadBytes")!.Invoke(codec,new[]{payload})!,Is.EqualTo(before));
        }
        [TestCaseSource(nameof(PositiveNames))]
        public void EveryFixedPositive_UsesRealClosedCodecAndExactIndependentNodeBytes(string name)
        {
            var c=LocalSaveContractFixtures.Case(name);var codec=LocalSaveContractFixtures.CodecFor(c);var source=Encoding.UTF8.GetBytes(c.Get("sourceEnvelopeUtf8").Text);var original=(byte[])source.Clone();var result=codec.Decode(source);Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Valid),result.ErrorCode);Assert.That(source,Is.EqualTo(original));var snapshot=LocalSaveContractFixtures.Property(result,"Snapshot")!;var payload=LocalSaveContractFixtures.Property(snapshot,"Payload")!;var actual=(byte[])typeof(LocalSaveCodec).GetMethod("PayloadBytes")!.Invoke(codec,new[]{payload})!;Assert.That(actual,Is.EqualTo(Encoding.UTF8.GetBytes(c.Get("expectedPayloadUtf8").Text)),"Entire actual typed payload differs from independent fixed expected");
            var type=snapshot.GetType();var offered=Activator.CreateInstance(type,LocalSaveContractFixtures.Property(snapshot,"Profile"),LocalSaveContractFixtures.Property(snapshot,"Catalog"),(long)c.Get("expectedEnvelope").Get("generation").Integer,payload)!;Assert.That(LocalSaveContractFixtures.Encode(codec,offered),Is.EqualTo(Encoding.UTF8.GetBytes(c.Get("expectedEnvelopeUtf8").Text)));var round=codec.Decode(LocalSaveContractFixtures.Encode(codec,offered));Assert.That(round.Status,Is.EqualTo(LocalSaveDecodeStatus.Valid),round.ErrorCode);
        }
        [Test]
        public void DuplicateNonCommittedPostClearClaimCannotCreateTwoAuthoritativeInstances()
        {
            var c=LocalSaveContractFixtures.Case("V2_REWARD_CLOSED_NO_REWARD");var codec=LocalSaveContractFixtures.CodecFor(c);var claim=Encoding.UTF8.GetString(c.Get("sourceEnvelope").Get("payload").Get("rewardClaims").Items[0].Canonical());var operation=Encoding.UTF8.GetString(c.Get("sourceEnvelope").Get("payload").Get("pendingOperations").Items[0].Canonical());var bytes=LocalSaveContractFixtures.MutatePayload(c,p=>p.Replace("\"rewardClaims\":["+claim+"]","\"rewardClaims\":["+claim+","+claim.Replace("reward-operation-1","reward-operation-2")+"]").Replace("\"pendingOperations\":["+operation+"]","\"pendingOperations\":["+operation+","+operation.Replace("reward-operation-1","reward-operation-2")+"]"));var result=codec.Decode(bytes);Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Corrupt));Assert.That(result.ErrorCode,Is.EqualTo("SAVE_DUPLICATE_ID"));
        }
        [Test]
        public void UnknownHistoricalFirstClearCatalogCannotBypassBoundRewardValuesEvenWithConsistentLedgerAndHashes()
        {
            var c=LocalSaveContractFixtures.Case("V1_FULL_FIRST_CLEAR");var codec=LocalSaveContractFixtures.CodecFor(c);var payload=c.Get("expectedPayload");string terminal=Encoding.UTF8.GetString(payload.Get("levels").Items[0].Get("firstClear").Get("terminal").Canonical());string oldCatalog=Encoding.UTF8.GetString(payload.Get("levels").Items[0].Get("firstClear").Get("terminal").Get("catalog").Canonical());string oldHash=payload.Get("levels").Items[0].Get("firstClear").Get("terminal").Get("catalog").Get("hashSha256").Text;string newHash=new string('f',64);string newCatalog=oldCatalog.Replace("completion-save-contract","foreign-completion").Replace(oldHash,newHash);string nextTerminal=terminal.Replace(oldCatalog,newCatalog).Replace("\"amount\":15","\"amount\":999");var entry=payload.Get("economyJournal").Items[0];string oldEntry=Encoding.UTF8.GetString(entry.Canonical());string oldChain=entry.Get("entryChainHashSha256").Text;string projection=oldEntry.Replace(",\"entryChainHashSha256\":\""+oldChain+"\"","").Replace("completion-save-contract","foreign-completion").Replace(oldHash,newHash).Replace("\"amount\":15","\"amount\":999");byte[] canonical=LocalSaveContractFixtures.Canonical(projection);string genesis=LocalSaveContractFixtures.Sha(Array.Empty<byte>());var combined=new byte[32+canonical.Length];for(int i=0;i<32;i++)combined[i]=byte.Parse(genesis.Substring(i*2,2),System.Globalization.NumberStyles.HexNumber);Buffer.BlockCopy(canonical,0,combined,32,canonical.Length);string chain=LocalSaveContractFixtures.Sha(combined);string nextEntry=oldEntry.Replace("completion-save-contract","foreign-completion").Replace(oldHash,newHash).Replace("\"amount\":15","\"amount\":999").Replace(oldChain,chain);var input=LocalSaveContractFixtures.MutatePayload(c,p=>p.Replace("\"terminal\":"+terminal,"\"terminal\":"+nextTerminal).Replace(oldEntry,nextEntry),true);var result=codec.Decode(input);Assert.That(result.Status,Is.EqualTo(LocalSaveDecodeStatus.Unsupported));Assert.That(result.ErrorCode,Is.EqualTo("SAVE_COMPLETION_BINDING_UNSUPPORTED"));
        }
